  ctx.stroke();
  const benchW = 60;
  const benchH = 30;
  ctx.fillStyle = "#8B4513";
  ctx.fillRect(centerX_px - openingW_px / 2 - benchW - 10, height - benchH - 5, benchW, benchH);
  ctx.fillRect(centerX_px + openingW_px / 2 + 10, height - benchH - 5, benchW, benchH);
