  const picnicY = height - 60;
  ctx.fillStyle = "#4b2e19";
  ctx.fillRect(picnicX, picnicY, 80, 40);
  ctx.fillRect(picnicX + 5, picnicY + 40, 5, 20);
  ctx.fillRect(picnicX + 70, picnicY + 40, 5, 20);
  const tableX1 = width * 0.2;
