  const carpetX = (tunnelWidth - PORTAL_TUNNEL_DIMENSIONS.carpetWidth) / 2;
  ctx.fillStyle = "#b22222";
  ctx.fillRect(carpetX * scale2, 0, PORTAL_TUNNEL_DIMENSIONS.carpetWidth * scale2, height);
  ctx.fillStyle = "rgba(0,0,0,0.05)";
  for (let y = 0; y < tunnelHeight; y += 1) {
    if (y % 2 === 0) {
      ctx.fillRect(carpetX * scale2, y * scale2, PORTAL_TUNNEL_DIMENSIONS.carpetWidth * scale2, 0.5 * scale2);
    }
  }
  ctx.fillStyle = "rgba(173, 216, 230, 0.3)";
  ctx.fillRect(0, 0, 0.5 * scale2, height);
  ctx.fillRect((tunnelWidth - 0.5) * scale2, 0, 0.5 * scale2, height);
