  for (let x = 100; x < width; x += 300) {
    ctx.fillStyle = "#4B0082";
    ctx.fillRect(x, 50, 60, 80);
    ctx.strokeStyle = "#FFD700";
    ctx.lineWidth = 3;
    ctx.strokeRect(x, 50, 60, 80);
  }
